G=load()
def f(g):
    out=[r[:] for r in g]; h,w=len(g),len(g[0])
    bg=Counter(c for r in g for c in r).most_common(1)[0][0]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg: continue
            st=[(i,j)]; seen={(i,j)}
            while st:
                a,b=st.pop()
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<h and 0<=nb<w and (na,nb) not in seen and g[na][nb]==g[i][j]:
                        seen.add((na,nb)); st.append((na,nb))
            rs=[a for a,_ in seen]; cs=[b for _,b in seen]
            top,bot,minc,maxc=min(rs),max(rs),min(cs),max(cs)
            for a in range(top+1,bot):
                for b_ in range(minc+1,maxc):
                    out[a][b_]=2
    return out
